#!/bin/sh
# Runs the meticulous-agent-traces uploader binary named by this plugin release,
# downloading and verifying it on first use.
#
# Usage: run-uploader.sh <uploader arguments...>
#
# bin/release.txt is generated by the publish workflow and names the
# release's commit, download base URL and per-platform sha256 checksums.
# Copies committed to a repository by `install-repo-hooks`, or piped from
# curl, have none, so they use the latest published release.txt, cached for
# an hour, and also cache that release's hook scripts, which committed copies
# of hook.sh hand over to so that they stay current.
# For local testing, METICULOUS_AGENT_TRACES_BINARY runs a given binary
# instead, METICULOUS_AGENT_TRACES_DOWNLOAD_BASE_URL overrides where
# binaries are downloaded from, and METICULOUS_AGENT_TRACES_RELEASE_URL
# where the latest release.txt is.
set -u

binary_name="meticulous-agent-traces"
release_file=""
# $0 isn't a file when the script is piped to sh.
if [ -f "$0" ]; then
  plugin_root="$(CDPATH='' cd -- "$(dirname -- "$0")/.." && pwd)" || exit 1
  release_file="$plugin_root/bin/release.txt"
fi
data_dir="$HOME/.meticulous/agent-traces"
releases_dir="$data_dir/releases"
# Must match latest_kit_bin_dir in hook.sh.
kit_dir="$data_dir/kit"
latest_release_url="${METICULOUS_AGENT_TRACES_RELEASE_URL:-https://snippet.meticulous.ai/agent-traces/v1/latest/release.txt}"

die() {
  echo "run-uploader.sh: $*" >&2
  exit 1
}

main() {
  if [ -n "${METICULOUS_AGENT_TRACES_BINARY:-}" ]; then
    exec "$METICULOUS_AGENT_TRACES_BINARY" "$@"
  fi
  uses_latest_release=false
  if [ -z "$release_file" ] || [ ! -f "$release_file" ]; then
    uses_latest_release=true
    release_file="$data_dir/latest-release.txt"
    refresh_latest_release
  fi
  platform="$(detect_platform)" ||
    die "unsupported platform: $(uname -s) $(uname -m)"
  commit="$(release_value commit)"
  expected_sha="$(release_value "sha256-$platform")"
  [ -n "$commit" ] && [ -n "$expected_sha" ] ||
    die "$release_file has no $platform build"
  base_url="${METICULOUS_AGENT_TRACES_DOWNLOAD_BASE_URL:-$(release_value base-url)}"

  binary="$releases_dir/$commit/$platform/$binary_name"
  if [ ! -x "$binary" ]; then
    download "$base_url/$platform/$binary_name" "$binary" "$expected_sha" binary
    prune_other_releases "$commit"
  fi
  if [ "$uses_latest_release" = true ]; then
    # Best effort: committed hooks keep working without it.
    cache_kit "$base_url" 2>/dev/null || true
  fi
  exec "$binary" "$@"
}

# Fetches this release's hook scripts into kit/current/bin. The directory is
# swapped in whole, so a hook never runs a half-written copy; one that runs
# mid-swap just finds none and carries on with its own.
cache_kit() {
  [ "$(cat "$kit_dir/current/commit" 2>/dev/null)" != "$commit" ] || return 0
  staging="$kit_dir/.staging.$$"
  rm -rf "$staging"
  for script in hook.sh run-uploader.sh; do
    script_sha="$(release_value "sha256-kit-$script")"
    if [ -z "$script_sha" ] ||
      ! (download "$1/kit/$script" "$staging/bin/$script" "$script_sha" script); then
      rm -rf "$staging"
      return 1
    fi
  done
  echo "$commit" >"$staging/commit"
  rm -rf "$kit_dir/.previous.$$"
  if [ -d "$kit_dir/current" ]; then
    mv "$kit_dir/current" "$kit_dir/.previous.$$"
  fi
  mv "$staging" "$kit_dir/current"
  rm -rf "$kit_dir/.previous.$$"
}

detect_platform() {
  case "$(uname -s)" in
    Darwin) os="darwin" ;;
    Linux) os="linux" ;;
    *) return 1 ;;
  esac
  case "$(uname -m)" in
    arm64 | aarch64) arch="arm64" ;;
    x86_64 | amd64) arch="x64" ;;
    *) return 1 ;;
  esac
  # Apple Silicon reports x86_64 under Rosetta; prefer the native build.
  if [ "$os" = "darwin" ] && [ "$(sysctl -n hw.optional.arm64 2>/dev/null)" = "1" ]; then
    arch="arm64"
  fi
  echo "$os-$arch"
}

# A failed refresh keeps using the cached copy, if there is one.
refresh_latest_release() {
  if [ -f "$release_file" ] &&
    [ -n "$(find "$release_file" -mmin -60 2>/dev/null)" ]; then
    return
  fi
  mkdir -p "$data_dir" || die "cannot create $data_dir"
  temp="$(mktemp "$release_file.XXXXXX")" || die "cannot create a temp file"
  if fetch "$latest_release_url" "$temp" 2>/dev/null &&
    grep -q '^commit ' "$temp"; then
    mv -f "$temp" "$release_file"
  else
    rm -f "$temp"
    [ -f "$release_file" ] || die "could not download $latest_release_url"
  fi
}

# release.txt lines are "<key> <value>".
release_value() {
  awk -v key="$1" '$1 == key { print $2; exit }' "$release_file"
}

# Concurrent downloads are harmless: each writes its own temp file and the
# final rename is atomic.
download() {
  url="$1"
  destination="$2"
  expected_sha="$3"
  kind="$4"
  mkdir -p "$(dirname "$destination")" || die "cannot create $(dirname "$destination")"
  temp="$(mktemp "$destination.XXXXXX")" || die "cannot create a temp file"
  trap 'rm -f "$temp"' EXIT
  fetch "$url" "$temp" || die "could not download $url"
  actual_sha="$(sha256_of "$temp")"
  [ "$actual_sha" = "$expected_sha" ] ||
    die "checksum mismatch for $url: expected $expected_sha, got $actual_sha"
  chmod 755 "$temp"
  # Apple Silicon refuses to run unsigned binaries; downloaded ones need an
  # ad-hoc signature, as distribution/install.sh does.
  if [ "$kind" = binary ] && [ "$(uname -s)" = "Darwin" ]; then
    codesign --force --sign - "$temp" || die "could not codesign $temp"
  fi
  mv -f "$temp" "$destination"
  trap - EXIT
}

fetch() {
  if command -v curl >/dev/null 2>&1; then
    curl -fsSL --retry 3 -o "$2" "$1"
  elif command -v wget >/dev/null 2>&1; then
    wget -q -O "$2" "$1"
  else
    die "neither curl nor wget is installed"
  fi
}

sha256_of() {
  if command -v sha256sum >/dev/null 2>&1; then
    sha256sum "$1" | cut -d' ' -f1
  else
    shasum -a 256 "$1" | cut -d' ' -f1
  fi
}

prune_other_releases() {
  for dir in "$releases_dir"/*; do
    if [ -d "$dir" ] && [ "$(basename "$dir")" != "$1" ]; then
      rm -rf "$dir"
    fi
  done
}

main "$@"
